"""Assemble cities.js from the read names + positions (+ state under each city)."""
import sys, json
import numpy as np
from PIL import Image
Image.MAX_IMAGE_PIXELS = None
S, OUT = sys.argv[1], sys.argv[2]
NAMES = """Уиндваль|Рикехина|Куилл|Реан|Клайвед|Кимнейсбей|Сактовье|Лимласса|Неленштат|Берзенстед|Синкехавн|Бергстид|Виндстректфельт|*|Хосст|Антеррей|Мьява|Питфур|Ильгард|Шафтон|Изулл|Гирстон|Ксанта|Винмут|Пакситон|Маундфилд|Альсбург|Медный Город|Блоксбург|Астрополис|Бордермут|Фангусрой|Квентисац|Эргостасьо|Энкефалико|Шимерун|Альтеррекольте|Айшервани|Люпимено|Скретин|Лас Кампос|Скрадробира|Гварбелак|Скатиониль|Пиривильон|Эрия|Апнеро|Килсвосс|Кушш|Рихабба|Каддавэй|Сангео|Глаустреалис|Абаджо|Ксино|Триповецк на Сельве|Коно|Арболета Верде|Крото|Фанатос|Ларго|Альбаурум|Малая|-|Кайява|Кохленмин|Бцуквидда|Царкейра|Хаупгемайн|Калактора|Кайпвайт|Уфермеренг|Айнхайтштадт|Крубрист|Калипар|Тарообун|Аль-Мальх|Джабаль|Хостайр|Арвара|Йока|Миккара|Траксивейл|Баланчар|Наора|Лиресхафен|Ковин|Фессейн|Бакайала|Риланей|Вракс|Бейрушуз|Амонтфельт|Везалиполь|Сандбэй|Чепстоу|Рантештадт|Вейдеплас|Шентау|Ванд|Сорт Ерсе|Люмидоус|Урс Никас|Пошатово|Ивинн|Ос Нак Карра|Кронкроу|Линдакейн|Харензара|Касца|Мурьевац|Крайсиволь|Ктарцегаш|Каривидон|Иррувирей|Икосента|Якойя|Таёномадзи|Сайеск|Уорш|Овинао|Гантао|Кова|Икки|Хунцзан|Саокен|Орокос|Аварис|Дзинцон|Офиелла|Идзина|Терран|Сонненгем|Ралисто|Кловирей|Оссентем|*|Солин|Ондата|Фульда|Асалене|Фрилль|Унтор|Каната|Порт-Ходук|Мирувер|Атрополь|Кабира|Вирсавва|Гьяртадон|Куарашат|Кушава|Кирьянас|Альвин|Катарпилс|*|Иффили|Хивентесс|Зерт|Энилот|Кливера|Шайтеколис|Триаолис|Ринкуабей|Канскрин|Аксель|Цзинхэ|Ингон|Гинцзан|Ченкхей|Сабара|Атокей|Апаритск|Миснойск|Юрза|Липта|Новус|Канпий|Гльвита|Вильяна|Кровен|Заренская|Икрань|Закатча|Валуй|Ирматск|Устула|Имвитон|Гредтерур|Сукра|Монолит|Ксой|Иркенза|Вейсланд|Линдвейр|Кьерн|Хоцка|Рейберг|Гракхат|Нуккель|Чакхид|Ипил|Ихацза""".split("|")
# labels that hold several names: [(name, fx, fy, bold)] — position as a fraction of the label box
SPLIT = {13: [("Врейтершах", .5, .2, True), ("Винфьель", .15, .8, False), ("Бергвикен", .85, .8, False)],
         136: [("Меркентоу", .3, .5, False), ("Аминно", .8, .6, True)],
         155: [("Карвис", .25, .25, True), ("Дьяреспилс", .7, .75, False)]}
raw = json.load(open(f'{S}/mapout/cities_raw.json'))
assert len(NAMES) == len(raw) == 203, (len(NAMES), len(raw))
fill = np.asarray(Image.open(f'{S}/mapout/full/L09.png'))
key = (fill[..., 0].astype(np.int32) << 16) | (fill[..., 1].astype(np.int32) << 8) | fill[..., 2]
key[fill[..., 3] < 200] = -1
def state_at(x, y):
    x, y = int(x), int(y); sub = key[max(0, y - 6):y + 7, max(0, x - 6):x + 7]; v = sub[sub >= 0]
    if not len(v): return None
    u, c = np.unique(v, return_counts=True); return '#%06x' % u[np.argmax(c)]
out = []
for c, name in zip(raw, NAMES):
    if name == "-": continue
    if name == "*":
        x, y, w, h = c['box']
        for nm, fx, fy, bold in SPLIT[c['id']]:
            px, py = x + w * fx, y + h * fy
            out.append(dict(name=nm, x=round(px), y=round(py), major=bold, state=state_at(px, py)))
        continue
    out.append(dict(name=name, x=c['x'], y=c['y'], major=c['major'], state=c['state']))
out.sort(key=lambda c: c['name'])
json.dump(out, open(OUT, 'w', encoding='utf-8'), ensure_ascii=False, separators=(',', ':'))
print(len(out), 'cities;', sum(1 for c in out if c['state']), 'inside a state;', sum(c['major'] for c in out), 'major')
